public class IterateWithTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("doubling from 1", "[1, 2, 4, 8, 16]",
                String.valueOf(IterateWith.generate(1, 5, x -> x * 2)));
        check("adding 5 from 3", "[3, 8, 13, 18]",
                String.valueOf(IterateWith.generate(3, 4, x -> x + 5)));
        check("squaring from 2", "[2, 4, 16, 256]",
                String.valueOf(IterateWith.generate(2, 4, x -> x * x)));
        check("count 1 -> just the seed", "[7]",
                String.valueOf(IterateWith.generate(7, 1, x -> x * x)));
        check("count 0 -> empty list", "[]",
                String.valueOf(IterateWith.generate(10, 0, x -> x + 1)));
        check("negative seed", "[-3, 0, 3]",
                String.valueOf(IterateWith.generate(-3, 3, x -> x + 3)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

