public class IterateWith {

    public static java.util.List<Integer> generate(
            int seed, int count, java.util.function.UnaryOperator<Integer> step) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        Integer current = seed;
        for (int i = 0; i < count; i++) {
            result.add(current);
            current = step.apply(current);
        }
        return result;
    }
}
